{"implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    dp = {0: (0.0, [])}
    for i in range(len(lengths)):
        len_i = lengths[i]
        score_i = scores[i]
        new_dp = dp.copy()
        for t, (sc, inds) in dp.items():
            new_t = t + len_i
            if new_t <= budget:
                new_score = sc + score_i
                new_inds = inds + [i]
                if new_t in new_dp:
                    existing_score, existing_inds = new_dp[new_t]
                    if new_score > existing_score or (new_score == existing_score and new_inds < existing_inds):
                        new_dp[new_t] = (new_score, new_inds)
                else:
                    new_dp[new_t] = (new_score, new_inds)
        dp = new_dp
    candidates = [(sc, -t, inds) for t, (sc, inds) in dp.items() if t <= budget]
    best = max(candidates)
    score, neg_t, inds = best
    return {'selected_indices': inds, 'tokens_used': -neg_t, 'total_score': score}"}
